requests.query:
query TX_ID_QUERY($offset: TransactionOffset!) {
  transactions(offset: $offset) {
    id
    protocolVersion
    raw
    hash
    unshieldedCreatedOutputs {
      owner
      intentHash
      tokenType
      value
      __typename
    }
    unshieldedSpentOutputs {
      owner
      intentHash
      tokenType
      value
      __typename
    }
    block {
      height
      hash
      author
      timestamp
      __typename
    }
    ... on RegularTransaction {
      identifiers
      fees {
        estimatedFees
        paidFees
        __typename
      }
      transactionResult {
        status
        segments {
          id
          success
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
